head.script:
// 이벤트 발생 순서 추적용
scwin.eventOrder = [];



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[multiselect > E > ondblclick]<br/>MultiSelect 컴포넌트를 마우스 왼쪽 버튼으로 더블 클릭할 때 발생합니다.",
    "validation" : [
        "선택값이 변경되면 onrowclick 이전에 onviewchange 이벤트가 발생합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    scwin.eventOrder = [];

    let eList = $c.gcm.createEList(["onviewchange", "onrowclick", "ondblclick"]);

    $c.gcm.createBasicMultiSelect('', eList);
}



// onviewchange 이벤트 핸들러 (선택값 변경 시 onrowclick 이전 발생)
scwin.target1_onviewchange = function (info) {
    scwin.eventOrder.push("onviewchange");
    wf_body_bottom.getObj("scwin").setReturnValue("===== target1 onviewchange =====");
}



// onrowclick 이벤트 핸들러
scwin.target1_onrowclick = function (info) {
    scwin.eventOrder.push("onrowclick");
    wf_body_bottom.getObj("scwin").setReturnValue("===== target1 onrowclick =====");
}



// ondblclick 이벤트 핸들러
scwin.target1_ondblclick = function (e) {
    scwin.eventOrder.push("ondblclick");
    wf_body_bottom.getObj("scwin").setReturnValue("===== target1 ondblclick =====");
}
